public boolean endsWith(final String str,final String suffix,final boolean ignoreCase){

'/*
* check if a string ends with a specified suffix (optionally case insensitive).
* @param str the string to check
* @param suffix the suffix to find
* @param ignore case indicates whether the compare should ignore case (case insensitive) or not
* @returns true if the string ends with the specified prefix or both are null.
*/

// edge case: if either str o suffix is null, return true if other is also null
if (str == null || suffix == null) {
return (str == null &&suffix == null);
}

// if suffix is empty, return true
if (suffix.length() == 0) {
return true;
}

// if str is shorter than suffix, return false
if (str.length() < suffix.length()) {
return false;
}

// if ignoreCase is true, convert both str and suffix to lowercase
if (ignoreCase) {
str = str.toLowerCase();
suffix = suffix.toLowerCase();
}

// check if str ends with suffix
return str.endsWith(suffix);
}
}

