public static File[] classPath(){
    // Split the class path by the OS-dependent path separator
    String separator = System.getProperty("path.separator");
    String classPath = System.getProperty("java.class.path");
    String[] classPathEntries = classPath.split(separator);

    // Get the list of all jar and zip files in the class path
    List<File> jarFiles = new ArrayList<>();
    for (String entry : classPathEntries) {
        if (entry.toLowerCase().endsWith(".jar") || entry.toLowerCase().endsWith(".zip")) {
            jarFiles.add(new File(entry));
        }
    }

    // Return the array of jar and zip files in the class path
    return jarFiles.toArray(new File[0]);
}

