private void enlarge(final int size) {
    if (size < 0) {
        throw new IllegalArgumentException("size must be non-negative");
    }

    final int oldCapacity = buffer.capacity();
    final int newCapacity = oldCapacity + size;
    final int expectedCapacity = buffer.limit() + size;

    if (newCapacity < expectedCapacity) {
        throw new RuntimeException("enlarge() method is not needed");
    }
    if (newCapacity > buffer.maxLength()) {
        throw new RuntimeException("enlarge() method is not needed");
    }

    buffer.resize(newCapacity);
}

